let activeFilter='all';let basket=JSON.parse(localStorage.getItem('md-basket')||'[]');let selectedParticipants=40;
const format=n=>new Intl.NumberFormat('sv-SE').format(n)+' kr';
function renderDeals(){const q=document.querySelector('#destination').value.toLowerCase();const mt=document.querySelector('#meetingType').value;const visible=deals.filter(d=>(activeFilter==='all'||d.type===activeFilter)&&(!q||(d.place+' '+d.name).toLowerCase().includes(q))&&(mt==='Alla mötestyper'||true));document.querySelector('#dealGrid').innerHTML=visible.map(d=>`<article class="deal-card"><div class="deal-image" style="background-image:url('${d.image}')"><span class="card-badge ${d.type}">${d.badge}</span><span class="score">${d.score} / 10</span></div><div class="deal-body"><div class="meta"><span>${d.place}</span><span>★ ${d.rating} · svar ${d.response}</span></div><h3>${d.name}</h3><p class="usp">${d.usp}</p><div class="included">${d.included.slice(0,4).map(x=>`<span>✓ ${x}</span>`).join('')}</div><div class="price-row"><div><small>MeetingDeal från</small><strong>${format(d.price)} / person</strong><small class="old-price">Ord. ${format(d.ordinary)}</small></div><div class="savings">Spara ${format((d.ordinary-d.price)*selectedParticipants)}<br><small>för ${selectedParticipants} personer</small></div></div></div><div class="card-actions"><button class="view" data-view="${d.id}">Se dealen</button><button data-add="${d.id}" aria-label="Lägg ${d.name} i offertkorg">${basket.includes(d.id)?'✓':'+'}</button></div></article>`).join('');document.querySelector('#emptyState').hidden=visible.length>0;bindCards()}
function bindCards(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>openDeal(b.dataset.view));document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>toggleBasket(b.dataset.add))}
function toggleBasket(id){basket=basket.includes(id)?basket.filter(x=>x!==id):[...basket,id].slice(0,5);localStorage.setItem('md-basket',JSON.stringify(basket));updateBasket();renderDeals()}
function updateBasket(){document.querySelector('#basketCount').textContent=basket.length;const list=basket.map(id=>deals.find(d=>d.id===id));document.querySelector('#basketItems').innerHTML=list.length?list.map(d=>`<div class="basket-item"><img src="${d.image}" alt=""><div><h4>${d.name}</h4><small>${format(d.price)} / person · ${d.id}</small></div><button data-remove="${d.id}" aria-label="Ta bort">×</button></div>`).join(''):'<p>Er offertkorg är tom. Lägg till upp till fem deals för att jämföra dem.</p>';document.querySelector('#basketTotal').textContent=format(list.reduce((s,d)=>s+d.price*selectedParticipants,0));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>toggleBasket(b.dataset.remove))}
function openDeal(id){const d=deals.find(x=>x.id===id);document.querySelector('#dealDetails').innerHTML=`<div class="detail-image" style="background-image:url('${d.image}')"></div><div class="detail-content"><span class="card-badge ${d.type}" style="position:static;display:inline-block">${d.badge}</span><div class="detail-top"><div><small>${d.place} · ${d.id}</small><h2>${d.name}</h2><p>${d.usp}</p></div><div class="detail-price"><small>Från</small><strong>${format(d.price)}</strong><small>/ person, exkl. moms</small></div></div><div class="detail-grid"><div><h3>Detta ingår</h3><p>${d.included.map(x=>'✓ '+x).join('<br>')}</p><h3>Mötet</h3><p>Kapacitet upp till ${d.capacity} deltagare. Modern mötesteknik, dagsljus och flexibla möbleringsalternativ.</p><h3>Giltiga datum</h3><p>${d.dates}</p></div><div class="calculator"><h3>Räkna på er grupp</h3><label>Antal deltagare<input id="calcPeople" type="number" min="8" value="${selectedParticipants}"></label><div class="calc-total"><span>MeetingDeal totalt</span><b id="calcDeal">${format(d.price*selectedParticipants)}</b></div><p>Ordinarie: <span id="calcOrd">${format(d.ordinary*selectedParticipants)}</span></p><p>Er besparing: <b id="calcSave">${format((d.ordinary-d.price)*selectedParticipants)}</b></p><button class="primary full" id="detailAdd">Lägg i offertkorg</button></div></div><p><small>Detta paket är exklusivt framtaget för MeetingDeal och kan endast säkras genom MeetingDeal.</small></p></div>`;const input=document.querySelector('#calcPeople');input.oninput=()=>{const n=Math.max(8,+input.value||8);document.querySelector('#calcDeal').textContent=format(d.price*n);document.querySelector('#calcOrd').textContent=format(d.ordinary*n);document.querySelector('#calcSave').textContent=format((d.ordinary-d.price)*n)};document.querySelector('#detailAdd').onclick=()=>{if(!basket.includes(id))toggleBasket(id);document.querySelector('#dealDialog').close();openBasket()};document.querySelector('#dealDialog').showModal()}
function openBasket(){document.querySelector('#basketDrawer').classList.add('open');document.querySelector('#drawerBackdrop').classList.add('open');document.querySelector('#basketDrawer').setAttribute('aria-hidden','false')}
function closeBasket(){document.querySelector('#basketDrawer').classList.remove('open');document.querySelector('#drawerBackdrop').classList.remove('open');document.querySelector('#basketDrawer').setAttribute('aria-hidden','true')}
function openRequest(){closeBasket();document.querySelector('#requestForm').hidden=false;document.querySelector('#requestSuccess').hidden=true;document.querySelector('#requestDialog').showModal()}
document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{document.querySelector('.filter.active').classList.remove('active');b.classList.add('active');activeFilter=b.dataset.filter;renderDeals()});
document.querySelector('#searchForm').onsubmit=e=>{e.preventDefault();selectedParticipants=Math.max(8,+document.querySelector('#participants').value||40);renderDeals();document.querySelector('#deals').scrollIntoView()};
document.querySelectorAll('[data-destination]').forEach(b=>b.onclick=()=>{document.querySelector('#destination').value=b.dataset.destination;renderDeals();document.querySelector('#deals').scrollIntoView()});
document.querySelector('#openBasket').onclick=openBasket;document.querySelector('[data-close]').onclick=closeBasket;document.querySelector('#drawerBackdrop').onclick=closeBasket;document.querySelector('[data-dialog-close]').onclick=()=>document.querySelector('#dealDialog').close();document.querySelectorAll('.open-request').forEach(b=>b.onclick=openRequest);document.querySelector('#openRequestTop').onclick=openRequest;document.querySelector('[data-request-close]').onclick=()=>document.querySelector('#requestDialog').close();document.querySelector('#requestForm').onsubmit=e=>{e.preventDefault();document.querySelector('#requestForm').hidden=true;document.querySelector('#requestSuccess').hidden=false};
updateBasket();renderDeals();
